import numpy as np
import pandas as pd
import random

def task_func(rows=3, cols=2, min_val=0, max_val=100, seed=0):
    np.random.seed(seed)
    random.seed(seed) # Set standard random seed as well just in case

    if min_val >= max_val:
        raise ValueError("min_val must be strictly less than max_val.")
    if rows < 0 or cols < 0:
        raise ValueError("Rows and cols must be non-negative integers.")

    matrix = np.random.randint(min_val, max_val, size=(rows, cols))
    return pd.DataFrame(matrix)
